await using var tx = await db.Database.BeginTransactionAsync(ct);

completion.MarkDone(userId, lessonId);
reviewSeeder.SeedDueItems(userId, lessonId);
outbox.Enqueue(new ReminderRecalculationRequested(userId));

await db.SaveChangesAsync(ct);
await tx.CommitAsync(ct);

// Relay: publish, then mark. A crash in between means a redelivery.
foreach (var message in await db.Outbox.Where(m => m.ProcessedAt == null).OrderBy(m => m.Sequence).Take(50).ToListAsync(ct))
{
    await bus.PublishAsync(message.Type, message.Payload, messageId: message.Id, ct);
    message.ProcessedAt = clock.GetUtcNow();
    await db.SaveChangesAsync(ct);
}

// Consumer: dedupe by message id inside the same transaction as the work.
if (await db.Inbox.AnyAsync(x => x.MessageId == messageId, ct)) return;
db.Inbox.Add(new InboxEntry(messageId));
await HandleAsync(message, ct);
await db.SaveChangesAsync(ct);
